"""Lists the sections (type code, sub-identifier, size, text or binary) of an object library part with GetLibraryPartSections.

Needs a loaded library with at least one object.
"""
import aclib

objects = aclib.RunTapirCommand ('GetAvailableLibraryParts', {'filterByTypeId': 'Object'})['libraryParts'][:1]
if not objects:
    raise SystemExit ('No object library part is loaded.')

aclib.PrintJson (aclib.RunTapirCommand ('GetLibraryPartSections', {
    'libraryParts': [{'index': objects[0]['index']}]
}))

"""Reads the text of the first text section (a script or the comment) of an object library part with GetLibraryPartSection.

Finds the section with GetLibraryPartSections. Needs a loaded library with at least one object.
"""
import aclib

objects = aclib.RunTapirCommand ('GetAvailableLibraryParts', {'filterByTypeId': 'Object'})['libraryParts'][:1]
if not objects:
    raise SystemExit ('No object library part is loaded.')
index = objects[0]['index']

sections = aclib.RunTapirCommand ('GetLibraryPartSections', {
    'libraryParts': [{'index': index}]
})['libraryParts'][0].get ('sections', [])
textSections = [section for section in sections if section.get ('isText') and section.get ('size', 0) > 0]
if not textSections:
    raise SystemExit ('The library part has no text section.')

aclib.PrintJson (aclib.RunTapirCommand ('GetLibraryPartSection', {
    'index': index,
    'sectionType': textSections[0]['sectionType'],
    'subIdent': textSections[0]['subIdent']
}))

"""Lists the default GDL parameters of an object library part, by name, with GetGDLParametersOfLibraryParts.

Nothing is placed and no defaults change. Needs a loaded library with at least one object.
"""
import aclib

objects = aclib.RunTapirCommand ('GetAvailableLibraryParts', {'filterByTypeId': 'Object'})['libraryParts'][:1]
if not objects:
    raise SystemExit ('No object library part is loaded.')

libraryPartName = objects[0]['documentName']
result = aclib.RunTapirCommand ('GetGDLParametersOfLibraryParts', {
    'libraryParts': [{'libraryPartName': libraryPartName}]
})['gdlParametersOfLibraryParts'][0]

print (libraryPartName)
for parameter in result['parameters']:
    if 'dimension1' in parameter:
        print ('  {} ({}): {} array {} x {}'.format (parameter['name'], parameter['displayName'], parameter['type'], parameter['dimension1'], parameter['dimension2']))
    else:
        print ('  {} ({}): {} = {}'.format (parameter['name'], parameter['displayName'], parameter['type'], parameter.get ('value')))

